{
  "title": "Is the new checkout better?",
  "setting": "A week at Cedar Cart",
  "mission": "Decide whether Cedar Cart should use a new checkout page. Give the team **a recommendation backed by a fair comparison**.",
  "deadline": "Update for {{product}} at 3:00 p.m. today",
  "panels": [
    {
      "title": "Checkout test plan",
      "metrics": [
        {
          "label": "Current purchase rate",
          "value": "10%",
          "note": "About 10 out of 100 visitors buy."
        },
        {
          "label": "Improvement worth detecting",
          "value": "2 percentage points",
          "note": "For example, a rise from 10% to 12%."
        }
      ],
      "note": "Visitors will be randomly assigned to the current page A or new page B."
    }
  ],
  "team": [
    {
      "id": "analyst",
      "role": "Data analyst",
      "expertise": "Plans comparisons and helps interpret results.",
      "ai": false
    },
    {
      "id": "product",
      "role": "Product manager",
      "expertise": "Wants a useful checkout decision without delaying the team.",
      "ai": false
    },
    {
      "id": "ai",
      "role": "AI assistant",
      "expertise": "Estimates sample sizes and checks calculations when asked.",
      "ai": true
    }
  ],
  "meters": [
    {
      "id": "confidence",
      "label": "Evidence for the decision",
      "start": 30,
      "goodWhen": "high"
    },
    {
      "id": "momentum",
      "label": "Product team momentum",
      "start": 70,
      "goodWhen": "high"
    }
  ],
  "skills": [
    {
      "id": "chance",
      "name": "Difference or chance",
      "practice": "For one comparison, write a sentence explaining how chance could produce a gap."
    },
    {
      "id": "sample",
      "name": "Sample size",
      "practice": "For one planned test, list the starting rate and the smallest improvement worth detecting."
    },
    {
      "id": "explain",
      "name": "Explain a test result",
      "practice": "Explain one test result to a non-data colleague in two plain-language sentences."
    }
  ],
  "startNodeId": "start",
  "nodes": [
    {
      "id": "start",
      "messages": [
        {
          "from": "product",
          "text": "The new page is ready. Can we make a call after the first 1,000 visitors see each version?"
        },
        {
          "from": "analyst",
          "text": "A sample is the group we observe. Too small a sample can miss a useful improvement, so let's set a target before we start."
        }
      ],
      "prompt": "How will you set the number of visitors to compare?",
      "choices": [
        {
          "id": "guess",
          "text": "Set a target of 4,000 visitors per version and start the test.",
          "quality": "fair",
          "replies": [
            {
              "from": "analyst",
              "text": "We can use that target, but we haven't checked how well it fits the improvement we care about."
            }
          ],
          "effects": [
            {
              "meter": "confidence",
              "change": 10
            },
            {
              "meter": "momentum",
              "change": -5
            }
          ],
          "timeJump": {
            "label": "One week later",
            "panel": {
              "title": "Results at 4,000 per version",
              "metrics": [
                {
                  "label": "Page A",
                  "value": "400 of 4,000",
                  "note": "10% purchased."
                },
                {
                  "label": "Page B",
                  "value": "480 of 4,000",
                  "note": "12% purchased."
                }
              ],
              "note": "Each visitor was randomly assigned to one version."
            }
          },
          "notes": [
            {
              "skill": "sample",
              "kind": "improve",
              "text": "A target can sound reasonable without being checked against the improvement you need to find.",
              "example": "Ask for a sample-size estimate using the starting rate and the improvement that matters."
            }
          ],
          "next": "long"
        },
        {
          "id": "estimate",
          "text": "Ask the AI for a sample-size estimate before starting the test.",
          "quality": "strong",
          "replies": [
            {
              "from": "ai",
              "text": "For 10% versus 12%, about 4,000 visitors per version gives roughly an 80% chance of detecting that improvement if it is real, using a common 5% test threshold."
            },
            {
              "from": "analyst",
              "text": "That estimate fits our goal. Let's use 4,000 per version as our target."
            }
          ],
          "effects": [
            {
              "meter": "confidence",
              "change": 25
            },
            {
              "meter": "momentum",
              "change": -10
            }
          ],
          "timeJump": {
            "label": "One week later",
            "panel": {
              "title": "Results at 4,000 per version",
              "metrics": [
                {
                  "label": "Page A",
                  "value": "400 of 4,000",
                  "note": "10% purchased."
                },
                {
                  "label": "Page B",
                  "value": "480 of 4,000",
                  "note": "12% purchased."
                }
              ],
              "note": "Each visitor was randomly assigned to one version."
            }
          },
          "notes": [
            {
              "skill": "sample",
              "kind": "good",
              "text": "You tied the sample target to the starting rate and the improvement the team cares about.",
              "example": null
            }
          ],
          "next": "long"
        },
        {
          "id": "early",
          "text": "Set a target of 1,000 visitors per version to get a faster answer.",
          "quality": "weak",
          "replies": [
            {
              "from": "product",
              "text": "That gets us an update sooner. Let's see what the first results look like."
            }
          ],
          "effects": [
            {
              "meter": "confidence",
              "change": -10
            },
            {
              "meter": "momentum",
              "change": 15
            }
          ],
          "timeJump": {
            "label": "Two days later",
            "panel": {
              "title": "Results at 1,000 per version",
              "metrics": [
                {
                  "label": "Page A",
                  "value": "100 of 1,000",
                  "note": "10% purchased."
                },
                {
                  "label": "Page B",
                  "value": "110 of 1,000",
                  "note": "11% purchased."
                }
              ],
              "note": "Each visitor was randomly assigned to one version."
            }
          },
          "notes": [
            {
              "skill": "sample",
              "kind": "improve",
              "text": "Speed helped the team get an early look, but the target was not checked against the improvement worth detecting.",
              "example": "Ask for a sample-size estimate before setting the stopping point."
            }
          ],
          "next": "short"
        }
      ]
    },
    {
      "id": "long",
      "messages": [
        {
          "from": "product",
          "text": "B is up from 10% to 12%. I'd like to put it in front of everyone."
        },
        {
          "from": "analyst",
          "text": "The gap is 2 percentage points. We still need to check how readily a gap like that could show up by chance."
        }
      ],
      "prompt": "What will you recommend?",
      "choices": [
        {
          "id": "launch",
          "text": "Launch B and tell the team it will raise purchases by 2 percentage points.",
          "quality": "weak",
          "replies": [
            {
              "from": "analyst",
              "text": "That's the gap we observed in the test, not a guaranteed future increase. We haven't checked the gap yet."
            }
          ],
          "effects": [
            {
              "meter": "confidence",
              "change": -15
            },
            {
              "meter": "momentum",
              "change": 15
            }
          ],
          "timeJump": null,
          "notes": [
            {
              "skill": "explain",
              "kind": "improve",
              "text": "The observed gap is not a promise of what will happen after launch.",
              "example": "\"B was 2 percentage points higher in this test; we should check how much chance could explain the gap.\""
            }
          ],
          "next": "unchecked"
        },
        {
          "id": "check",
          "text": "Ask the AI to check the gap, then recommend B if the evidence supports it.",
          "quality": "strong",
          "replies": [
            {
              "from": "ai",
              "text": "If the pages were equally effective, a gap at least this large in either direction would occur about 0.4% of the time. That's below the common 5% threshold."
            },
            {
              "from": "analyst",
              "text": "The result supports recommending B, though the future improvement may differ from the 2-point gap we observed."
            },
            {
              "from": "product",
              "text": "That's clear enough for the team to move ahead with B."
            }
          ],
          "effects": [
            {
              "meter": "confidence",
              "change": 30
            },
            {
              "meter": "momentum",
              "change": 10
            }
          ],
          "timeJump": null,
          "notes": [
            {
              "skill": "chance",
              "kind": "good",
              "text": "You checked how likely a gap this large would be if the pages were equally effective.",
              "example": null
            },
            {
              "skill": "explain",
              "kind": "good",
              "text": "You used the check to make a recommendation without promising the same future lift.",
              "example": null
            }
          ],
          "next": "supported"
        },
        {
          "id": "hold",
          "text": "Hold the launch and ask for more evidence before making a recommendation.",
          "quality": "fair",
          "replies": [
            {
              "from": "product",
              "text": "I can hold the launch, but I'd like to know what the current results tell us first."
            }
          ],
          "effects": [
            {
              "meter": "confidence",
              "change": 5
            },
            {
              "meter": "momentum",
              "change": -15
            }
          ],
          "timeJump": null,
          "notes": [
            {
              "skill": "chance",
              "kind": "improve",
              "text": "Holding avoids an unsupported claim, but checking the current gap could inform the decision now.",
              "example": "Ask the AI to check how readily the observed gap could occur by chance."
            }
          ],
          "next": "held"
        }
      ]
    },
    {
      "id": "short",
      "messages": [
        {
          "from": "product",
          "text": "B is at 11% and A is at 10%. Can we launch B now?"
        },
        {
          "from": "analyst",
          "text": "The gap is 1 percentage point. With this smaller sample, we should check what the result can tell us."
        }
      ],
      "prompt": "What will you recommend?",
      "choices": [
        {
          "id": "check",
          "text": "Ask the AI to check the gap, then continue the test if the evidence is unclear.",
          "quality": "strong",
          "replies": [
            {
              "from": "ai",
              "text": "If the pages were equally effective, a gap at least this large in either direction would occur about 47% of the time. This result doesn't rule out chance."
            },
            {
              "from": "analyst",
              "text": "The result doesn't prove the pages are equal, either. Let's plan a larger comparison before deciding."
            },
            {
              "from": "product",
              "text": "I'll hold the launch while we agree on the next test plan."
            }
          ],
          "effects": [
            {
              "meter": "confidence",
              "change": 25
            },
            {
              "meter": "momentum",
              "change": -10
            }
          ],
          "timeJump": null,
          "notes": [
            {
              "skill": "chance",
              "kind": "good",
              "text": "You checked the gap and treated an unclear result as a reason to gather more evidence, not as proof of no difference.",
              "example": null
            },
            {
              "skill": "explain",
              "kind": "good",
              "text": "You gave the team a practical next step while keeping the result's limits clear.",
              "example": null
            }
          ],
          "next": "held"
        },
        {
          "id": "launch",
          "text": "Launch B and tell the team its higher purchase rate shows it is better.",
          "quality": "weak",
          "replies": [
            {
              "from": "analyst",
              "text": "B did better in this sample, but we haven't checked whether chance could explain the gap."
            }
          ],
          "effects": [
            {
              "meter": "confidence",
              "change": -20
            },
            {
              "meter": "momentum",
              "change": 15
            }
          ],
          "timeJump": null,
          "notes": [
            {
              "skill": "explain",
              "kind": "improve",
              "text": "A higher observed rate alone doesn't establish that B is better.",
              "example": "\"B is ahead so far, but we need to check whether the gap could be chance.\""
            }
          ],
          "next": "unchecked"
        }
      ]
    }
  ],
  "endings": [
    {
      "id": "supported",
      "outcome": "The team launches B after checking the evidence. In the test, purchases were 10% on A and 12% on B; the future difference is not guaranteed."
    },
    {
      "id": "unchecked",
      "outcome": "The team launches B without checking whether the observed gap could be due to chance. The apparent improvement may not persist."
    },
    {
      "id": "held",
      "outcome": "The team holds the launch and plans its next evidence check. The product decision remains open."
    }
  ],
  "summary": [
    "Choose a sample target using the starting rate and the smallest improvement worth detecting.",
    "A hypothesis test checks how readily a gap could appear by chance if there were no real difference.",
    "Describe the observed result and its uncertainty without promising the same future outcome."
  ]
}

{
  "title": "E se você pudesse ver a luz chegar?",
  "setting": "Laboratório imaginário",
  "mission": "Explore como a luz chega a uma tela para descobrir **se ela age como pacote, como onda ou dos dois jeitos**.",
  "deadline": null,
  "panels": [],
  "team": [
    {
      "id": "physics",
      "role": "Física",
      "expertise": "Ajuda a interpretar o comportamento da luz.",
      "ai": false
    },
    {
      "id": "guide",
      "role": "Monitor do laboratório",
      "expertise": "Conhece os controles da fonte de luz e da tela.",
      "ai": false
    }
  ],
  "meters": [],
  "skills": [
    {
      "id": "packets",
      "name": "Energia em pacotes",
      "practice": "Explique em uma frase o que é um quantum de luz de uma mesma cor."
    },
    {
      "id": "duality",
      "name": "Onda e partícula",
      "practice": "Descreva em duas frases como a mesma luz pode deixar pontos e formar faixas."
    }
  ],
  "startNodeId": "start",
  "nodes": [
    {
      "id": "start",
      "messages": [
        {
          "from": "physics",
          "text": "Um quantum é um pacote de energia. Para luz de uma mesma cor, os pacotes têm a mesma energia."
        },
        {
          "from": "guide",
          "text": "Nossa fonte emite luz de uma só cor. Você pode deixá-la forte ou enviá-la bem fraquinha para uma tela sensível."
        }
      ],
      "prompt": "Como você começa a explorar a luz?",
      "choices": [
        {
          "id": "bright",
          "text": "Acendo a fonte forte e observo a tela.",
          "quality": "fair",
          "replies": [
            {
              "from": "guide",
              "text": "A tela parece iluminada de modo contínuo. Assim, você ainda não consegue distinguir as chegadas individuais."
            }
          ],
          "effects": [],
          "timeJump": null,
          "notes": [
            {
              "skill": "packets",
              "kind": "improve",
              "text": "Com a luz forte, as chegadas se misturam na tela. Experimente diminuir a luz para observá-las separadamente.",
              "example": null
            }
          ],
          "next": "bright-next"
        },
        {
          "id": "dim",
          "text": "Enfraqueço a fonte e observo a tela.",
          "quality": "strong",
          "replies": [
            {
              "from": "guide",
              "text": "A tela registra pontos separados. Cada chegada transfere à tela um pacote de energia da luz dessa cor."
            }
          ],
          "effects": [],
          "timeJump": null,
          "notes": [
            {
              "skill": "packets",
              "kind": "good",
              "text": "Você reduziu a luz para observar as chegadas individuais dos pacotes de energia.",
              "example": null
            }
          ],
          "next": "dim-next"
        }
      ]
    },
    {
      "id": "dim-next",
      "messages": [
        {
          "from": "physics",
          "text": "Os pontos mostram chegadas individuais. Agora podemos procurar um comportamento parecido com o de uma onda."
        },
        {
          "from": "guide",
          "text": "Posso colocar uma placa com duas aberturas finas entre a fonte e a tela."
        }
      ],
      "prompt": "O que você experimenta agora?",
      "choices": [
        {
          "id": "one-opening",
          "text": "Uso uma abertura e observo os pontos.",
          "quality": "fair",
          "replies": [
            {
              "from": "guide",
              "text": "Os pontos continuam chegando separadamente, mas você não testou o efeito das duas aberturas."
            }
          ],
          "effects": [],
          "timeJump": null,
          "notes": [
            {
              "skill": "duality",
              "kind": "improve",
              "text": "Uma abertura permite observar os pontos, mas não testa o efeito das duas. Experimente deixar as duas abertas.",
              "example": null
            }
          ],
          "next": "points"
        },
        {
          "id": "two-openings",
          "text": "Uso duas aberturas e acumulo os pontos.",
          "quality": "strong",
          "replies": [
            {
              "from": "physics",
              "text": "Com muitos pontos, aparecem faixas claras e escuras, como no encontro de ondas. Cada chegada ainda é registrada como um ponto."
            }
          ],
          "effects": [],
          "timeJump": null,
          "notes": [
            {
              "skill": "duality",
              "kind": "good",
              "text": "Você acumulou os pontos para revelar um padrão de ondas sem perder de vista as chegadas individuais.",
              "example": null
            }
          ],
          "next": "both"
        }
      ]
    },
    {
      "id": "bright-next",
      "messages": [
        {
          "from": "physics",
          "text": "Podemos procurar um comportamento de onda colocando duas aberturas finas no caminho da luz."
        },
        {
          "from": "guide",
          "text": "A fonte ainda está forte, mas posso enfraquecê-la antes de continuar."
        }
      ],
      "prompt": "Como você continua o experimento?",
      "choices": [
        {
          "id": "keep-bright",
          "text": "Mantenho a luz forte e uso duas aberturas.",
          "quality": "fair",
          "replies": [
            {
              "from": "physics",
              "text": "A tela mostra faixas claras e escuras, como no encontro de ondas. Com a luz forte, você não distingue os pontos individuais."
            }
          ],
          "effects": [],
          "timeJump": null,
          "notes": [
            {
              "skill": "duality",
              "kind": "improve",
              "text": "As duas aberturas revelaram as faixas. Para observar também as chegadas individuais, repita com luz mais fraca.",
              "example": null
            }
          ],
          "next": "stripes"
        },
        {
          "id": "dim-two",
          "text": "Enfraqueço a luz e uso duas aberturas.",
          "quality": "strong",
          "replies": [
            {
              "from": "physics",
              "text": "A tela registra pontos separados. Ao acumular muitos deles, aparecem faixas claras e escuras, como no encontro de ondas."
            }
          ],
          "effects": [],
          "timeJump": null,
          "notes": [
            {
              "skill": "duality",
              "kind": "good",
              "text": "Você mudou a intensidade e usou duas aberturas para observar tanto os pontos quanto o padrão de ondas.",
              "example": null
            }
          ],
          "next": "both"
        }
      ]
    }
  ],
  "endings": [
    {
      "id": "points",
      "outcome": "Você observou a luz chegar em pontos separados. Ainda falta testar as duas aberturas para explorar o padrão parecido com o de ondas."
    },
    {
      "id": "stripes",
      "outcome": "Você observou faixas parecidas com as que aparecem quando ondas se encontram. Com a fonte forte, as chegadas individuais ficaram escondidas."
    },
    {
      "id": "both",
      "outcome": "A luz chegou em pontos individuais e, com o acúmulo, formou faixas parecidas com as de ondas. O mesmo experimento revelou os dois comportamentos."
    }
  ],
  "summary": [
    "Um quantum é um pacote de energia; para luz de uma mesma cor, esses pacotes têm a mesma energia.",
    "A luz pode ser detectada em chegadas individuais e também formar padrões característicos de ondas."
  ]
}

{
  "title": "Qual dose preparar?",
  "setting": "Plantão na unidade",
  "mission": "Confira a prescrição de paracetamol para uma criança e decida **qual dose pode ser preparada com segurança**.",
  "deadline": "Retorno do médico plantonista em 20 minutos",
  "panels": [
    {
      "title": "Dados disponíveis",
      "metrics": [
        {
          "label": "Peso confirmado",
          "value": "20 kg",
          "note": null
        },
        {
          "label": "Prescrição",
          "value": "400 mg por via oral",
          "note": "Dose única, agora."
        },
        {
          "label": "Referência da unidade",
          "value": "10 mg/kg por dose",
          "note": "Para este caso."
        },
        {
          "label": "Solução oral disponível",
          "value": "200 mg/mL",
          "note": "Paracetamol, conforme o rótulo."
        }
      ],
      "note": null
    }
  ],
  "team": [
    {
      "id": "nurse",
      "role": "Enfermeira responsável",
      "expertise": "Acompanha a conferência de medicamentos na unidade.",
