    },
    {
      "id": "doctor",
      "role": "Médico plantonista",
      "expertise": "Avalia dúvidas e pode corrigir a prescrição.",
      "ai": false
    },
    {
      "id": "ai",
      "role": "Assistente de IA",
      "expertise": "Ajuda a conferir cálculos com os dados informados.",
      "ai": true
    }
  ],
  "meters": [
    {
      "id": "safety",
      "label": "Segurança da conferência",
      "start": 50,
      "goodWhen": "high"
    },
    {
      "id": "time",
      "label": "Tempo disponível",
      "start": 75,
      "goodWhen": "high"
    }
  ],
  "skills": [
    {
      "id": "weight",
      "name": "Dose por peso",
      "practice": "Calcule uma dose para um peso fictício e confira o resultado em mg."
    },
    {
      "id": "order",
      "name": "Conferência da prescrição",
      "practice": "Confira dose, unidade e via em uma prescrição fictícia e no rótulo correspondente."
    },
    {
      "id": "communication",
      "name": "Comunicação da dúvida",
      "practice": "Escreva uma mensagem de duas frases ao médico com um cálculo fictício e uma dúvida objetiva."
    }
  ],
  "startNodeId": "start",
  "nodes": [
    {
      "id": "start",
      "messages": [
        {
          "from": "nurse",
          "text": "O peso foi confirmado agora. Antes de preparar, precisamos conferir a dose, a via e o produto."
        },
        {
          "from": "doctor",
          "text": "Vou atender outra criança, mas posso esclarecer a prescrição se houver alguma dúvida."
        }
      ],
      "prompt": "Como você começa a conferência?",
      "choices": [
        {
          "id": "ai-check",
          "text": "Peço à IA para calcular a dose pelo peso e compará-la com a prescrição.",
          "quality": "strong",
          "replies": [
            {
              "from": "ai",
              "text": "20 kg × 10 mg/kg = 200 mg por dose. A prescrição indica 400 mg; confira os dados e peça esclarecimento antes de preparar."
            }
          ],
          "effects": [
            {
              "meter": "safety",
              "change": 15
            },
            {
